import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
os.makedirs(UPLOAD_DIR, exist_ok=True)

# Supported output formats for document conversion
SUPPORTED_FORMATS = ['pdf', 'docx', 'html', 'txt', 'odt']

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

def validate_session(token):
    # Session validation against Redis - simplified
    if not token or len(token) < 16:
        return None
    # In production this checks Redis; here we trust the gateway's pre-validation
    return {'user_id': token[:8], 'tier': 'standard'}

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    auth = validate_session(request.headers.get('X-Session-Token'))
    if not auth:
        return jsonify({'error': 'unauthorized'}), 401

    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')
    extra_args = request.form.get('options', '')

    if output_format not in SUPPORTED_FORMATS:
        return jsonify({'error': f'unsupported format: {output_format}'}), 400

    filename = secure_filename(uploaded.filename)
    if not filename:
        return jsonify({'error': 'invalid filename'}), 400

    job_id = generate_job_id(filename)
    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{filename}")
    output_path = os.path.join(UPLOAD_DIR, f"{job_id}_output.{output_format}")

    uploaded.save(input_path)

    # Build conversion command using LibreOffice
    # The 'options' field allows passing extra LibreOffice macro parameters
    # for advanced formatting (margins, orientation, etc.)
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR}"

    if extra_args:
        # Allow power users to pass infilter/outfilter options
        cmd += f" {extra_args}"

    cmd += f" {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=120,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'conversion failed',
                'job_id': job_id,
                'detail': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # LibreOffice names output based on input filename
        actual_output = os.path.join(UPLOAD_DIR, f"{job_id}_{os.path.splitext(filename)[0]}.{output_format}")

        if os.path.exists(actual_output):
            return send_file(actual_output, as_attachment=True)
        else:
            return jsonify({'error': 'output file not found', 'job_id': job_id}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'conversion timeout', 'job_id': job_id}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/v2/convert/batch', methods=['POST'])
def batch_convert():
    auth = validate_session(request.headers.get('X-Session-Token'))
    if not auth:
        return jsonify({'error': 'unauthorized'}), 401

    manifest = request.get_json()
    if not manifest or 'urls' not in manifest:
        return jsonify({'error': 'invalid manifest'}), 400

    # Fetch and convert URLs - uses curl for reliability with redirects
    results = []
    for entry in manifest.get('urls', [])[:5]:
        url = entry.get('url', '')
        fmt = entry.get('format', 'pdf')

        if fmt not in SUPPORTED_FORMATS:
            results.append({'url': url, 'status': 'unsupported_format'})
            continue

        job_id = generate_job_id(url)
        dl_path = os.path.join(UPLOAD_DIR, f"{job_id}_download")

        # Download the file
        dl_cmd = f"curl -sL -o {dl_path} --max-time 30 '{url}'"
        subprocess.run(dl_cmd, shell=True, timeout=35)

        if os.path.exists(dl_path):
            results.append({'url': url, 'job_id': job_id, 'status': 'queued'})
        else:
            results.append({'url': url, 'status': 'download_failed'})

    return jsonify({'batch_results': results})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
